/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getARIA = require( './aria/get.js' );
var setARIA = require( './aria/set.js' );

var getEncode = require( './encode/get.js' );
var setEncode = require( './encode/set.js' );

var getFrom = require( './from/get.js' );
var setFrom = require( './from/set.js' );

var getProperties = require( './properties/get.js' );

var getTriggers = require( './triggers/get.js' );
var setTriggers = require( './triggers/set.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );

var getZIndex = require( './zindex/get.js' );
var setZIndex = require( './zindex/set.js' );


// VARIABLES //

var debug = logger( 'vega:mark:main' );


// MAIN //

/**
* Mark constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.type - mark type
* @param {boolean} [options.aria=true] - boolean indicating whether to include ARIA attributes in SVG output
* @param {(boolean|Signal|Object)} [options.clip=false] - setting indicating whether to clip marks to a specified shape
* @param {string} [options.description] - text description of a mark for ARIA accessibility
* @param {Encoding} [options.encode] - visual encoding rules for mark properties
* @param {DataSource} [options.from] - object describing the data a mark should visualize
* @param {boolean} [options.interactive=true] - boolean indicating whether a mark can serve as an input event source
* @param {(string|Field)} [options.key] - data field to use as a unique key for data binding
* @param {string} [options.name] - unique name
* @param {string} [options.role] - metadata string indicating the role of a mark
* @param {Object} [options.sort] - comparator for sorting mark items
* @param {(string|Array<string>)} [options.style] - custom styles to apply to a mark
* @param {Array<Transform>} [options.transforms=[]] - list of post-encoding transforms to apply after any "encode" blocks and which operate directly on mark scenegraph items
* @param {Array<Trigger>} [options.triggers=[]] - list of triggers for modifying mark properties in response to signal changes
* @param {number} [options.zindex=0] - integer z-index indicating the layering of a mark relative to other marks
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Mark} mark instance
*
* @example
* var mark = new Mark({
*     'type': 'line'
* });
* // returns <Mark>
*/
function Mark( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof Mark ) ) {
		return new Mark( options );
	}
	EventEmitter.call( this );
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
		if ( k === 'on' ) {
			this._triggers = opts[ k ]; // set an alias
		} else if ( k === 'triggers' ) {
			this._on = opts[ k ]; // set an alias
		}
	}
	// Check for required properties...
	if ( !hasProp( options, 'type' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the mark type.' );
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		if ( k === 'on' ) {
			// Avoid conflict with event emitter method:
			k = 'triggers';
		}
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Mark, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Mark
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Mark, 'name', 'Mark' );

/**
* Boolean indicating whether to include ARIA attributes in SVG output.
*
* @name aria
* @memberof Mark.prototype
* @type {boolean}
* @default true
*
* @example
* var mark = new Mark({
*     'type': 'line',
*     'aria': true
* });
*
* var v = mark.aria;
* // returns true
*/
setReadWriteAccessor( Mark.prototype, 'aria', getARIA, setARIA );

/**
* Visual encoding rules for mark properties.
*
* @name encode
* @memberof Mark.prototype
* @type {(Encoding|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
* var Encoding = require( '@stdlib/plot/vega/mark/base/encoding' );
*
* var mark = new Mark({
*     'type': 'line',
*     'encode': new Encoding({
*         'enter': new EncodingSet({
*              'stroke': new Value({
*                  'value': 'steelblue'
*              })
*         })
*     })
* });
*
* var v = mark.encode;
* // returns {...}
*/
setReadWriteAccessor( Mark.prototype, 'encode', getEncode, setEncode );

/**
* Mark data source.
*
* @name from
* @memberof Mark.prototype
* @type {(Object|void)}
*
* @example
* var DataSource = require( '@stdlib/plot/vega/mark/data-source' );
*
* var mark = new Mark({
*     'type': 'line',
*     'from': new DataSource({
*         'data': 'foo'
*     })
* });
*
* var v = mark.from;
* // returns <DataSource>
*/
setReadWriteAccessor( Mark.prototype, 'from', getFrom, setFrom );

/**
* Mark properties.
*
* @name properties
* @memberof Mark.prototype
* @type {Array<string>}
*
* @example
* var mark = new Mark({
*     'type': 'line'
* });
*
* var v = mark.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Mark.prototype, 'properties', getProperties );

/**
* List of triggers for modifying mark properties in response to signal changes.
*
* @name triggers
* @memberof Mark.prototype
* @type {Array<Trigger>}
*
* @example
* var mark = new Mark({
*     'type': 'line',
*     'triggers': []
* });
*
* var v = mark.triggers;
* // returns []
*/
setReadWriteAccessor( Mark.prototype, 'triggers', getTriggers, setTriggers );

/**
* Graphical mark type.
*
* @name type
* @memberof Mark.prototype
* @type {string}
*
* @example
* var mark = new Mark({
*     'type': 'line'
* });
*
* var v = mark.type;
* // returns 'line'
*/
setReadWriteAccessor( Mark.prototype, 'type', getType, setType );

/**
* Integer z-index indicating the layering of a mark relative to other marks.
*
* @name zindex
* @memberof Mark.prototype
* @type {string}
* @default 0
*
* @example
* var mark = new Mark({
*     'type': 'line',
*     'zindex': 2
* });
*
* var v = mark.zindex;
* // returns 2
*/
setReadWriteAccessor( Mark.prototype, 'zindex', getZIndex, setZIndex );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Mark.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var mark = new Mark({
*     'type': 'line'
* });
*
* var v = mark.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Mark.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Mark;
